sys_script_include.script:
var GetSystemPropertyValue = Class.create();
GetSystemPropertyValue.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    // Get property value
    getPropertyValue: function() {
        var propertyName = this.getParameter('sysparm_property_name');

        if (!propertyName) {
            gs.log('Missing property name parameter', 'GetSystemPropertyValue');
            return '{}';
        }

        var propertyValue = gs.getProperty(propertyName, '{}');
        gs.log('Retrieved property value for ' + propertyName, 'GetSystemPropertyValue');

        return propertyValue;
    },

    // Check if property exists
    checkPropertyExists: function() {
        var propertyName = this.getParameter('sysparm_property_name');

        if (!propertyName) {
            gs.log('Missing property name parameter', 'GetSystemPropertyValue');
            return 'false';
        }

        var propertyGr = new GlideRecord('sys_properties');
        propertyGr.addQuery('name', propertyName);
        propertyGr.query();

        var exists = propertyGr.hasNext();
        gs.log('Property ' + propertyName + ' exists: ' + exists, 'GetSystemPropertyValue');

        return exists.toString();
    },

    type: 'GetSystemPropertyValue'
});
